insert into public.tests (slug, category_id, title, depth, emoji, is_premium, is_custom, questions) values
  ('quel-le-amant-e-es-tu', 'amour', 'Quel·le amant·e es-tu ?', 'leger', '💘', false, false, '[{"q":"Un premier rendez-vous réussi, c''est surtout :","options":["Une conversation qui ne s''arrête plus","Un fou rire incontrôlable","Un silence confortable, sans rien à prouver","Une tension électrique dès la poignée de main"]},{"q":"Tu montres ton attachement plutôt par :","options":["Des mots, beaucoup de mots","Des attentions discrètes et régulières","Du temps offert sans compter","Le contact physique"]},{"q":"Ta plus grande peur en amour :","options":["Qu''on s''ennuie de toi","Perdre ta liberté","Ne jamais être vraiment compris·e","Que ça devienne trop sérieux trop vite"]},{"q":"Après une dispute, tu as besoin de :","options":["Tout régler immédiatement, en parlant","Un peu d''espace avant de revenir","Un câlin plus que des explications","Écrire ce que tu ressens avant d''en parler"]},{"q":"Ton style de séduction :","options":["Direct·e, tu assumes tes intentions","Taquin·e, tu joues avec les sous-entendus","Patient·e, tu laisses venir","Généreux·se, tu impressionnes par les attentions"]},{"q":"Un texto reçu au réveil idéal :","options":["Quelque chose de drôle","Quelque chose de doux","Rien, tu préfères la surprise en vrai","Un vrai message, pas juste un emoji"]},{"q":"Ce qui te fait vraiment craquer :","options":["L''intelligence et la répartie","La douceur et l''écoute","L''audace et la confiance","L''humour et la légèreté"]},{"q":"En couple, tu es plutôt :","options":["Fusionnel·le, tu adores le duo","Indépendant·e, tu gardes ton monde à toi","Équilibré·e entre les deux","Ça dépend totalement de la personne"]},{"q":"Une soirée parfaite à deux :","options":["Un restaurant qu''on découvre ensemble","Canapé, plaid, aucun programme précis","Une activité un peu folle, hors des sentiers battus","Cuisiner ensemble, sans pression"]},{"q":"Tu tombes amoureux·se plutôt :","options":["Vite, sur un coup de tête","Lentement, en apprenant à connaître","Rarement, mais alors intensément","Par surprise, quand tu ne t''y attends pas"]},{"q":"Ce que tu offres le plus facilement :","options":["Ton temps","Ton honnêteté, même quand ça pique","Ta présence rassurante","Ton énergie et ton enthousiasme"]},{"q":"Face à la jalousie, tu es :","options":["Plutôt confiant·e, ça ne te traverse pas souvent","Tu la ressens mais tu la gardes pour toi","Tu en parles ouvertement","Ça dépend beaucoup du contexte"]},{"q":"Le compliment qui te touche le plus :","options":["\"Tu me fais rire comme personne\"","\"Je me sens en sécurité avec toi\"","\"Tu me surprends toujours\"","\"Tu me comprends sans que j''explique\""]},{"q":"Dans les moments difficiles de l''autre, tu es :","options":["Celui·celle qui trouve les mots","Celui·celle qui est juste là, en silence","Celui·celle qui propose des solutions","Celui·celle qui fait diversion avec légèreté"]},{"q":"Ta relation idéale ressemble surtout à :","options":["Une aventure qui continue","Un port d''attache stable","Une amitié très intense","Un mélange de complicité et de désir"]}]'::jsonb),
  ('sur-une-ile-deserte-survivrais-tu', 'aventure', 'Sur une île déserte, survivrais-tu ?', 'leger', '🏝️', false, false, '[{"q":"Le bateau coule, tu as 30 secondes pour attraper une chose :","options":["Un couteau","Ton téléphone (même sans réseau)","De la nourriture","Rien, tu aides quelqu''un d''autre en priorité"]},{"q":"Premier réflexe une fois sur la plage :","options":["Chercher de l''eau douce","Faire le tour de l''île","Construire un abri","Repérer un point en hauteur pour observer"]},{"q":"Face à un animal inconnu qui approche :","options":["Tu recules calmement","Tu observes avant d''agir","Tu tentes de l''apprivoiser","Tu paniques un peu, franchement"]},{"q":"Le feu ne prend pas depuis une heure, tu :","options":["Insistes avec la même méthode, obstiné·e","Changes complètement de technique","Fais une pause pour ne pas t''énerver","Demandes de l''aide si tu n''es pas seul·e"]},{"q":"S''il y a d''autres naufragés avec toi, tu deviens vite :","options":["Celui·celle qui organise tout","Celui·celle qui rassure le groupe","Celui·celle qui part explorer seul·e","Celui·celle qui fait ce qu''on lui demande, sans discuter"]},{"q":"Ta plus grande ressource dans cette situation :","options":["Ton sang-froid","Ta débrouillardise","Ton moral à toute épreuve","Ta capacité à motiver les autres"]},{"q":"Après une semaine, ce qui te manque le plus :","options":["Une vraie conversation","Une douche chaude","Ton lit","Savoir ce qui se passe dans le monde"]},{"q":"Un avion passe au loin sans te voir, tu :","options":["Restes optimiste, un autre passera","Es frustré·e mais tu tiens bon","Accélères tous tes plans de signal","Relativises, ce n''était qu''une question de temps"]},{"q":"Ta priorité numéro un sur l''île :","options":["Assurer la survie de base","Garder le moral, le tien et celui des autres","Trouver un moyen de partir","Explorer et comprendre où tu es"]},{"q":"Si tu dois choisir un seul compagnon d''infortune :","options":["Quelqu''un de calme et fiable","Quelqu''un de drôle, pour tenir le moral","Quelqu''un de très débrouillard","Peu importe, tu t''adaptes à qui il y a"]},{"q":"La nuit, seul·e face au bruit de la jungle :","options":["Tu restes éveillé·e, aux aguets","Tu te forces à dormir, tu en as besoin","Tu te racontes des histoires pour te rassurer","Tu chantes ou parles tout haut pour te tenir compagnie"]},{"q":"Tu trouves une caisse échouée, potentiellement utile mais lourde :","options":["Tu l''ouvres tout de suite sur place","Tu la traînes jusqu''à ton abri d''abord","Tu la laisses, trop risqué","Tu inspectes les alentours avant d''y toucher"]},{"q":"Ce qui te ferait le plus craquer nerveusement :","options":["L''ennui et la routine","Le silence total, l''absence d''autres humains","Ne pas savoir combien de temps ça va durer","Perdre le contrôle sur la situation"]},{"q":"Un mois plus tard, tu es surtout devenu·e :","options":["Plus calme et plus patient·e qu''avant","Plus débrouillard·e que tu ne le pensais","Plus attaché·e aux petites choses simples","Plus déterminé·e et endurci·e"]},{"q":"Le sauvetage arrive enfin, ta première pensée :","options":["\"Enfin une vraie douche\"","\"J''ai appris des choses sur moi\"","\"J''ai hâte de raconter ça\"","\"Je vais rater ce silence, étrangement\""]}]'::jsonb),
  ('quel-type-d-humour-as-tu', 'humour', 'Quel type d''humour as-tu ?', 'leger', '😂', false, false, '[{"q":"Ce qui te fait le plus rire :","options":["Un jeu de mots bien placé","Une situation absurde","L''auto-dérision de quelqu''un","Un timing parfait, sans un mot de trop"]},{"q":"Dans un groupe, tu es plutôt :","options":["Celui·celle qui balance la vanne","Celui·celle qui rebondit sur ce que dit l''autre","Celui·celle qui rit le plus fort","Celui·celle qui observe avant de placer LA phrase"]},{"q":"Ton humour préféré au cinéma :","options":["Le nonsense complet","L''ironie fine et les dialogues ciselés","Le comique de situation, très visuel","L''humour noir, qui dérange un peu"]},{"q":"Face à une gaffe embarrassante (la tienne) :","options":["Tu en ris la première, avant les autres","Tu la racontes encore des mois après","Tu préfères en rire seul·e, plus tard","Tu transformes ça en running gag"]},{"q":"Une blague qui tombe à plat, tu :","options":["Enchaînes avec une autre, sans complexe","Ris de la situation elle-même","Assumes le silence, ça aussi c''est drôle","Expliques la blague, pour le pire"]},{"q":"Ton compte à texto le plus drôle contient surtout :","options":["Des memes bien ciblés","Des captures de conversations absurdes","Des messages vocaux improvisés","Des jeux de mots que personne ne comprend sauf toi"]},{"q":"L''humour que tu ne supportes pas :","options":["Celui qui rabaisse quelqu''un","Celui qui explique trop la chute","Celui qui se répète tout le temps","Celui qui essaie trop fort"]},{"q":"Tu préfères faire rire :","options":["Un inconnu, pour le défi","Tes proches, qui connaissent tes références","Toi-même, avant tout","Un public entier, si l''occasion se présente"]},{"q":"Ton réflexe face à une situation tendue :","options":["Détendre l''atmosphère avec une blague","Rester sérieux·se, ce n''est pas le moment","Attendre après coup pour en rire","Ça dépend totalement du contexte"]},{"q":"Une comédie que tu pourrais revoir en boucle plutôt qu''un drame primé :","options":["Toujours","Ça dépend vraiment de ton humeur","Rarement, tu préfères varier","Oui, mais en cachette de tout le monde"]},{"q":"Ton type d''ironie :","options":["Très visible, tout le monde comprend","Discrète, seuls certains la captent","Tu n''es pas ironique, tu es direct·e","Ça dépend de qui est en face"]},{"q":"Face à une blague sur toi-même (par un proche) :","options":["Tu ris et tu enchéris","Tu ris, mais tu prépares ta revanche","Ça dépend du ton employé","Tu préfères qu''on évite, franchement"]},{"q":"Ton humour au travail/à l''école :","options":["Très présent, même dans les moments sérieux","Réservé aux pauses, jamais pendant le travail","Discret, un sourire en coin suffit","Ça dépend beaucoup de l''ambiance du groupe"]},{"q":"Ce qui te fait le plus marrer chez les autres :","options":["Leur spontanéité","Leur autodérision","Leur sens du timing","Leur capacité à rire d''eux-mêmes sans se dévaloriser"]},{"q":"Si ton humour était une saison :","options":["L''été, léger et sans complexe","L''automne, plus doux-amer","Le printemps, plein d''énergie","L''hiver, plus noir et sec"]}]'::jsonb),
  ('de-quoi-reves-tu-secretement-en-amour', 'amour', 'De quoi rêves-tu secrètement en amour ?', 'profond', '💘', false, false, '[{"q":"Le geste romantique que tu espères sans jamais le demander :","options":["Qu''on se souvienne d''un détail dit en passant","Qu''on prenne un vrai risque pour toi","Qu''on t''écrive quelque chose, sur papier","Qu''on organise une surprise sans occasion particulière"]},{"q":"Le scénario que tu imagines parfois, un peu gêné·e de te l''avouer :","options":["Tout quitter avec quelqu''un, sur un coup de tête","Vieillir avec la même personne, très longtemps","Une histoire qui commence par hasard, ailleurs","Retrouver quelqu''un du passé, différemment"]},{"q":"Ce que tu voudrais qu''on comprenne de toi sans avoir à l''expliquer :","options":["Que ton silence n''est pas de l''indifférence","Que tu as besoin d''être rassuré·e parfois","Que tu aimes fort, même si ça se voit peu","Que tu as peur de trop en demander"]},{"q":"Le mot que tu n''as jamais osé dire en premier :","options":["\"Je t''aime\"","\"J''ai besoin de toi\"","\"Reste\"","\"Recommençons\""]},{"q":"Ta définition secrète d''une histoire réussie :","options":["Se sentir totalement soi-même","Grandir ensemble sans se perdre","Rire tous les jours, même dans le pire","Ne jamais douter d''être choisi·e"]},{"q":"Ce que tu espères qu''on remarque chez toi en premier :","options":["Ta loyauté","Ton humour","Ta sensibilité","Ta force tranquille"]},{"q":"Le fantasme le plus doux que tu gardes pour toi :","options":["Une déclaration publique et un peu folle","Une vie simple, dans un endroit précis que tu imagines","Qu''on te choisisse contre toute logique","Un silence partagé qui veut tout dire"]},{"q":"Ce que tu ne dis jamais à voix haute par pudeur :","options":["Que tu es plus fragile que tu n''en as l''air","Que tu rêves encore de grandes histoires","Que tu as besoin de mots pour te sentir aimé·e","Que tu doutes parfois de le mériter"]},{"q":"Si tu pouvais rejouer un souvenir amoureux en boucle :","options":["Le tout début, l''insouciance","Un moment de complicité silencieuse","Une déclaration inattendue","Une réconciliation après une dispute"]},{"q":"Ce à quoi tu penses en secret quand une relation te manque :","options":["Pas une personne précise, juste l''idée d''être choisi·e","Une personne précise, encore aujourd''hui","Le sentiment de sécurité que ça donnait","La version de toi que tu étais dans cette histoire"]},{"q":"La chose que tu voudrais offrir sans qu''on te le demande :","options":["Une présence sans faille","La liberté d''être imparfait·e","Des projets fous à deux","Une stabilité que tu n''as pas toujours eue"]},{"q":"Ta plus grande peur, jamais formulée à voix haute :","options":["Aimer plus fort que tu n''es aimé·e en retour","Passer à côté par peur de te lancer","Devenir quelqu''un d''autre pour plaire","Ne jamais retrouver ce que tu as connu une fois"]},{"q":"Le genre de complicité que tu recherches sans le dire clairement :","options":["Pouvoir tout dire, même le pire","Rire de rien avec quelqu''un","Se comprendre sans un mot","Se sentir en sécurité, tout simplement"]},{"q":"S''il existait une phrase magique pour rassurer l''autre définitivement, tu dirais :","options":["\"Je ne pars nulle part\"","\"Tu comptes plus que tu ne le penses\"","\"On trouvera toujours une solution ensemble\"","\"Je t''aime tel·le que tu es, pas tel que tu voudrais être\""]},{"q":"Au fond, ce que tu espères vraiment en amour :","options":["Être vu·e, vraiment, une bonne fois pour toutes","Ne plus avoir à te protéger autant","Construire quelque chose qui dure","Vivre une histoire qui sort de l''ordinaire"]}]'::jsonb),
  ('que-caches-tu-meme-a-tes-meilleurs-amis', 'amitie', 'Que caches-tu même à tes meilleurs amis ?', 'profond', '🤝', false, false, '[{"q":"Ce que tu ne racontes jamais, même à ton entourage proche :","options":["Tes vrais moments de doute","Certaines de tes anciennes relations","Ce que tu penses vraiment de toi","Tes ambitions les plus folles, par peur du jugement"]},{"q":"Quand tu vas mal, ton premier réflexe :","options":["Faire comme si de rien n''était","Te confier à une seule personne triée sur le volet","Trouver une excuse logistique pour t''isoler","Attendre qu''on remarque, sans jamais le dire"]},{"q":"Le sujet que tu esquives systématiquement en groupe :","options":["L''argent","Tes relations amoureuses passées","Ta famille","Tes échecs professionnels ou scolaires"]},{"q":"Ce que tes amis seraient surpris d''apprendre sur toi :","options":["À quel point tu doutes de toi en réalité","Un talent ou une passion que tu ne montres jamais","Une période difficile que tu as traversée seul·e","Ce que tu penses vraiment de certaines décisions du groupe"]},{"q":"Face à un compliment, en vrai tu :","options":["N''y crois qu''à moitié, intérieurement","L''acceptes en façade, mais tu le rejettes en silence","Le savoures sans le montrer","Cherches ce qu''on attend de toi en retour"]},{"q":"Ce que tu gardes pour toi par peur de déranger :","options":["Tes besoins émotionnels","Tes difficultés financières","Ta fatigue, physique ou mentale","Tes désaccords avec le groupe"]},{"q":"S''il existait un journal que personne ne lirait jamais, tu y écrirais surtout :","options":["Ce que tu ressens vraiment sur le moment","Des regrets que tu n''exprimes jamais","Des rêves que tu trouves trop ambitieux pour les dire","Des vérités sur des relations que tu entretiens"]},{"q":"Ta plus grande insécurité, que personne ne devine :","options":["Ne pas être à la hauteur de l''image qu''on a de toi","Être oublié·e si tu arrêtais de faire des efforts","Ne jamais vraiment savoir ce que tu veux","Décevoir les gens qui comptent sur toi"]},{"q":"Ce que tu simules le plus souvent en société :","options":["L''enthousiasme","La confiance en toi","Le calme","L''indifférence"]},{"q":"La dernière fois que tu as pleuré seul·e, tu :","options":["N''en as parlé à personne","L''as évoqué vaguement, sans détails","L''as gardé secret volontairement","Ne t''en souviens même plus, ça arrive trop rarement pour compter"]},{"q":"Ce que tu penses vraiment de ton groupe d''amis, sans le dire :","options":["Qu''il te manque parfois une vraie profondeur","Que tu t''y sens un peu seul·e malgré tout","Que tu joues souvent un rôle","Que tout va bien, en fait, tu n''as juste rien à cacher ici"]},{"q":"Le secret le plus anodin que tu gardes quand même :","options":["Une habitude un peu honteuse","Un avis impopulaire sur quelqu''un du groupe","Une chose que tu adores et que tu n''assumes pas","Un mensonge blanc jamais corrigé"]},{"q":"Ce qui te retient de tout dire, même à tes proches :","options":["La peur d''être jugé·e","La peur de peser sur les autres","L''habitude de tout gérer seul·e","Le sentiment que ça ne changerait rien"]},{"q":"Si tes amis découvraient une part cachée de toi, tu penses qu''ils seraient :","options":["Surpris, mais pas inquiets","Un peu blessés de ne pas l''avoir su plus tôt","Compréhensifs, plus que tu ne le crois","Indifférents, en fait ça n''a pas grande importance"]},{"q":"Ce que tu voudrais qu''on te demande, sans jamais oser le suggérer toi-même :","options":["\"Comment tu vas vraiment ?\"","\"Tu as besoin d''aide ?\"","\"Qu''est-ce que tu ne me dis pas ?\"","\"Est-ce que je peux faire quelque chose pour toi ?\""]}]'::jsonb),
  ('quelle-peur-inavouee-te-freine-vraiment', 'aventure', 'Quelle peur inavouée te freine vraiment ?', 'profond', '🏝️', false, false, '[{"q":"Ce qui te tétanise le plus, sans que tu l''admettes facilement :","options":["Décevoir quelqu''un que tu admires","Être ordinaire, sans rien de remarquable","Faire un choix et le regretter ensuite","Être seul·e, au sens large du terme"]},{"q":"Face à une opportunité qui te fait peur, tu :","options":["La laisses passer en te trouvant une bonne excuse","Fonces quand même, la peur au ventre","Repousses la décision le plus longtemps possible","En parles à quelqu''un avant de te décider"]},{"q":"Ce que tu évites soigneusement, sans vraiment te l''avouer :","options":["Les conversations qui pourraient mal tourner","Les engagements à long terme","Te retrouver seul·e avec tes pensées","Demander de l''aide, même quand tu en aurais besoin"]},{"q":"Le scénario qui te hante un peu, en silence :","options":["Réaliser trop tard que tu as fait le mauvais choix","Être oublié·e par les gens que tu aimes","Ne jamais devenir la personne que tu voudrais être","Perdre le contrôle sur ta propre vie"]},{"q":"Ta réaction face à un échec, en vrai :","options":["Tu le minimises devant les autres, mais ça te ronge","Tu en fais une leçon, presque trop vite","Tu évites d''y repenser complètement","Tu en parles beaucoup, pour t''en libérer"]},{"q":"Ce qui te fait le plus douter de toi, en secret :","options":["Ne pas savoir si tu es à ta place","Te comparer aux autres, malgré toi","Avoir l''impression de jouer un rôle","Ne pas savoir ce que tu veux vraiment"]},{"q":"S''il fallait nommer ta peur la plus profonde :","options":["Ne jamais être vraiment connu·e par les autres","Rester bloqué·e là où tu es","Perdre quelqu''un d''important sans prévenir","Ne pas avoir été à la hauteur, au final"]},{"q":"Face au changement, ta première réaction intérieure :","options":["De l''excitation mêlée d''angoisse","Une résistance immédiate, même si tu la caches","Une envie de tout contrôler d''avance","Une envie de fuir, freinée par la raison"]},{"q":"Ce que tu redoutes le plus qu''on découvre chez toi :","options":["Que tu n''as pas toujours confiance en toi","Que tu es plus sensible que tu ne le montres","Que tu improvises bien plus que tu ne l''admets","Que tu as parfois besoin qu''on te rassure"]},{"q":"Le mot qui te met le plus mal à l''aise, sans savoir pourquoi :","options":["\"Toujours\"","\"Jamais\"","\"Seul·e\"","\"Trop tard\""]},{"q":"Ce qui t''empêche parfois d''avancer, que tu identifies rarement :","options":["Le besoin d''être sûr·e avant d''agir","La peur de l''opinion des autres","Un vieux souvenir que tu ne veux pas revivre","L''habitude de te sous-estimer"]},{"q":"Ta stratégie inconsciente pour éviter cette peur :","options":["Rester très occupé·e, tout le temps","Garder un contrôle strict sur ton quotidien","Éviter les situations qui pourraient l''activer","En rire, pour ne pas y penser sérieusement"]},{"q":"Si cette peur disparaissait demain, la première chose que tu ferais :","options":["Un choix que tu repousses depuis longtemps","Dire une vérité que tu retiens","Te lancer dans quelque chose de nouveau","Simplement, te sentir plus léger·e"]},{"q":"Ce qui t''aide, malgré tout, à avancer avec cette peur :","options":["Le soutien de quelques personnes proches","Le fait d''avoir déjà surmonté pire","Une forme de discipline personnelle","Le temps, simplement, qui fait son travail"]},{"q":"Au fond, cette peur dit surtout de toi que :","options":["Tu tiens à ce que tu construis","Tu attends beaucoup de toi-même","Tu as besoin de sécurité pour t''épanouir","Tu es plus courageux·se que tu ne le crois, justement parce qu''elle existe"]}]'::jsonb),
  ('de-quoi-ris-tu-en-cachette', 'humour', 'De quoi ris-tu en cachette ?', 'profond', '😂', false, false, '[{"q":"Le genre de contenu que tu regardes sans le dire à personne :","options":["Des vidéos totalement absurdes et sans intérêt","Des télé-réalités que tu juges publiquement","Des comptes de memes très ciblés, presque gênants","Des vieux sketchs que tu connais par cœur"]},{"q":"Ce qui te fait rire tout·e seul·e, dans ta tête, sans prévenir personne :","options":["Un souvenir précis et un peu absurde","Une répartie que tu n''as jamais osé dire à voix haute","Une private joke avec toi-même","L''image mentale d''une situation improbable"]},{"q":"Le type d''humour que tu juges publiquement mais qui te fait secrètement rire :","options":["Les blagues très potaches","L''humour un peu méchant, bien dosé","Les jeux de mots vraiment nuls","L''humour absurde jusqu''à l''inconfort"]},{"q":"Ce que tu trouves drôle chez les autres sans jamais le leur dire :","options":["Leurs petites manies","Leur façon très sérieuse de raconter des banalités","Leurs expressions du visage sans qu''ils le sachent","Leur mauvaise foi assumée"]},{"q":"Le fou rire le plus incontrôlable que tu gardes pour toi, en public tu restes stoïque, mais dedans :","options":["Tu pleures de rire silencieusement","Tu dois te mordre la joue pour ne rien montrer","Tu détournes le regard pour ne pas craquer","Tu ris nerveusement et tu espères que ça passe pour autre chose"]},{"q":"Ta private joke la plus ancienne, que tu n''as jamais expliquée à personne d''autre :","options":["Elle vient d''un vieux souvenir d''enfance","Elle vient d''un malentendu jamais corrigé","Elle vient d''une phrase mal comprise, devenue culte pour toi seul·e","Tu ne t''en souviens même plus, seul le rire est resté"]},{"q":"Le moment où tu ris le plus, en toute discrétion :","options":["Seul·e devant ton téléphone","Pendant une réunion sérieuse, à un détail hors sujet","En repensant à une gaffe de quelqu''un d''autre","Devant ton propre reflet, sans raison précise"]},{"q":"Ce que tu trouves drôle mais que tu n''assumerais jamais publiquement :","options":["Les chutes des autres, malgré toi","Certaines répliques limites","Le comique de répétition, même au bout de la 10e fois","L''humour très premier degré, sincèrement"]},{"q":"S''il existait une caméra cachée sur tes vrais fous rires, on découvrirait surtout :","options":["Que tu ris beaucoup plus que tu ne le montres","Que tu as un humour bien plus noir qu''en apparence","Que tu ris souvent de toi-même, en cachette","Que rien ne te fait autant rire que l''absurde total"]},{"q":"Ce qui te fait rire malgré toi, même quand ce n''est pas le moment :","options":["Les silences gênants","Les catastrophes mineures","Les personnes qui se prennent très au sérieux","Tes propres maladresses"]},{"q":"Ton humour honteux, celui que tu ne dévoilerais qu''à une seule personne :","options":["Très enfantin, presque bête","Très noir, presque dérangeant","Très potache, presque gênant","Très nul, presque touchant"]},{"q":"Ce que tu ne pourrais jamais expliquer à quelqu''un pourquoi ça te fait rire :","options":["Une expression très précise sur un visage","Un mot mal prononcé, systématiquement","Une situation totalement banale, sortie de son contexte","Le sérieux extrême de quelqu''un d''autre"]},{"q":"La dernière fois que tu as ri tout·e seul·e sans raison apparente, c''était pour :","options":["Un souvenir qui t''est revenu d''un coup","Une pensée totalement absurde","Une private joke que tu t''es faite à toi-même","Aucune raison précise, juste comme ça"]},{"q":"Ce que révèle vraiment ton humour secret sur toi :","options":["Que tu es plus léger·ère que ce que tu montres","Que tu observes beaucoup plus que tu ne le dis","Que tu as un besoin constant de décompresser","Que tu gardes une part d''enfance bien vivante"]},{"q":"Si on te filmait à ton insu pendant une semaine, la scène la plus drôle serait :","options":["Toi en train de rire seul·e devant ton téléphone","Toi en train d''imiter quelqu''un dans le vide","Toi en train de te parler à toi-même","Toi en train de rire d''une private joke incompréhensible pour les autres"]}]'::jsonb),
  ('quel-reve-d-enfance-n-as-tu-jamais-realise', 'valeurs', 'Quel rêve d''enfance n''as-tu jamais réalisé ?', 'profond', '🧭', false, false, '[{"q":"Le métier que tu voulais faire, petit·e, avant qu''on te dise que ce n''était \"pas sérieux\" :","options":["Quelque chose d''artistique","Un métier d''aventure ou d''exploration","Un métier qui aide directement les gens","Quelque chose de complètement improbable, avec le recul"]},{"q":"Ce que tu voulais absolument devenir en grandissant :","options":["Quelqu''un de connu, d''une façon ou d''une autre","Quelqu''un de libre, sans horaires ni contraintes","Quelqu''un d''important pour beaucoup de monde","Simplement, quelqu''un d''heureux — c''était déjà ambitieux à l''époque"]},{"q":"Le talent que tu pensais avoir, enfant, et que tu n''as jamais développé :","options":["Un talent artistique","Un talent sportif","Un don pour inventer des histoires","Un sens du leadership naturel"]},{"q":"Ce que tu regrettes un peu de ne jamais avoir tenté :","options":["Un instrument de musique jamais appris","Un voyage jamais fait","Une compétition jamais tentée","Une passion jamais prise au sérieux"]},{"q":"La raison principale qui t''a fait abandonner ce rêve :","options":["Le \"réalisme\" qu''on t''a inculqué trop tôt","Le manque de temps, tout simplement","La peur de ne pas être assez doué·e","Un autre chemin qui s''est imposé à toi"]},{"q":"Si tu croisais ta version enfant aujourd''hui, elle serait surtout :","options":["Fière de certaines choses, déçue d''autres","Surprise par le chemin pris","Un peu triste que ce rêve précis soit resté de côté","Plutôt fascinée par qui tu es devenu·e, en fait"]},{"q":"Ce rêve d''enfance, tu y repenses :","options":["Rarement, mais avec une pointe de nostalgie","Souvent, presque comme un regret actif","Seulement quand quelque chose te le rappelle","Jamais consciemment, mais il refait surface en rêve parfois"]},{"q":"Ce qui te retient encore aujourd''hui d''au moins l''essayer, même modestement :","options":["Le manque de temps","La peur d''être \"trop vieux/vieille\" pour commencer","La peur de gâcher un joli souvenir en le confrontant à la réalité","Rien de concret, juste l''inertie du quotidien"]},{"q":"Si tu pouvais reprendre ce rêve maintenant, sans aucun risque, tu :","options":["Foncerais immédiatement","Y penserais sérieusement, pour la première fois depuis longtemps","Hésiterais, par peur de la déception","Le garderais comme un joli rêve, sans le brusquer"]},{"q":"La personne qui a le plus influencé l''abandon de ce rêve :","options":["Un parent, avec de bonnes intentions","Toi-même, par manque de confiance","Le système scolaire ou professionnel","Personne en particulier, la vie a juste pris ce chemin"]},{"q":"Ce que ce rêve dit vraiment de qui tu étais, enfant :","options":["Que tu avais une grande imagination","Que tu voulais déjà te sentir libre","Que tu voulais déjà avoir un impact","Que tu étais déjà quelqu''un de sensible"]},{"q":"La version \"adulte\" et réaliste de ce rêve pourrait ressembler à :","options":["Un hobby que tu reprends pour toi","Une reconversion, un jour, pourquoi pas","Un projet à côté, sans en faire un métier","Rien de concret — et c''est très bien comme ça aussi"]},{"q":"Ce qui t''empêcherait aujourd''hui de simplement essayer, sans pression :","options":["Le regard des autres","Le manque de temps réel","La peur de ne plus être douée pour ça","Honnêtement, rien — tu n''y avais juste pas repensé"]},{"q":"Ce rêve, s''il n''avait jamais existé, ta vie serait :","options":["Assez similaire, au fond","Différente, mais tu ne saurais pas dire comment","Plus simple, mais moins riche","Impossible à imaginer sans lui, il t''a façonné·e malgré tout"]},{"q":"Aujourd''hui, ce que ce rêve d''enfance a laissé chez toi :","options":["Une sensibilité particulière pour ce domaine","Un petit regret doux, sans amertume","Une curiosité qui ressort parfois","Une leçon sur ce qui compte vraiment pour toi"]}]'::jsonb),
  ('quel-est-ton-petit-plaisir-coupable-financier', 'argent', 'Quel est ton petit plaisir coupable financier ?', 'leger', '💰', false, false, '[{"q":"La dépense que tu justifies toujours, même quand elle n''est pas raisonnable :","options":["La nourriture, livraisons comprises","Les vêtements ou accessoires","Les sorties et expériences","Les objets pour la maison, sans vraie utilité"]},{"q":"Ce que tu achètes en te disant \"c''est la dernière fois\" — et ce n''est jamais la dernière fois :","options":["Un café ou une boisson hors de prix","Un abonnement dont tu n''as pas vraiment besoin","Un vêtement que tu ne porteras que deux fois","Un gadget totalement superflu"]},{"q":"Ta technique pour te sentir mieux après une dépense impulsive :","options":["Tu te dis que tu le méritais","Tu compenses en économisant ailleurs, artificiellement","Tu évites de regarder ton compte quelques jours","Tu en parles avec humour à quelqu''un, pour désamorcer"]},{"q":"Le moment où tu craques le plus facilement niveau dépenses :","options":["Quand tu es stressé·e","Quand tu es content·e et que tu veux te faire plaisir","Quand tu es avec certaines personnes en particulier","Quand une promotion ou un compte à rebours apparaît"]},{"q":"Ce que tu ne diras jamais le prix exact à tes proches :","options":["Un vêtement ou accessoire","Une sortie ou un abonnement","Un objet acheté sur un coup de tête","Quelque chose que tu considères comme \"inutile\" aux yeux des autres"]},{"q":"Ton rapport à l''application bancaire :","options":["Tu la regardes en boucle, avec un peu d''anxiété","Tu évites de l''ouvrir trop souvent","Tu la consultes froidement, sans émotion particulière","Tu la regardes seulement après une grosse dépense, avec appréhension"]},{"q":"Ce que tu achètes plus pour l''image que pour l''usage réel :","options":["Des vêtements ou accessoires de marque","Des équipements sportifs jamais vraiment utilisés","Des objets déco \"parce que ça fait bien\"","Des sorties surtout pour les montrer, 